#[test]
fn bind_value_function_pair_tag_type_arg_is_not_ts_stripped() {
    // TRAP2 DISCRIMINATOR: a valid plain-JS RELATIONAL expression that LOOKS like a
    // tagged-template-with-type-arguments (``tag<string>`x` ``) must be rewritten from
    // the plain-JS (`mjs`) AST WITHOUT TS-stripping. Under TSX, OXC reinterprets
    // ``tag<string>`x` `` as a tagged template whose `<string>` is TS type arguments;
    // the TS strip then removes them, corrupting the expression to ``tag`x` `` — a
    // BEHAVIORAL change (a relational compare becomes a tagged-template call). Official
    // svelte@5.56.3 parses it as plain JS and emits the RELATIONAL form
    // (`$.bind_value(input, tag < string > `x`, …)`), keeping the `<string>` operands.
    // The plain-JS rewrite lane must reproduce that (Verter keeps the author's
    // no-whitespace bytes `tag<string>`x``), and MUST NOT emit the stripped ``tag`x` ``.
    let js = emit(
        "<script>let v = $state(\"\");</script>\n<input bind:value={tag<string>`x`, (x) => v = x} />\n",
        "App.svelte",
    );
    // POSITIVE: the relational `<string>` operands survive (not stripped as type args).
    assert!(
        js.contains("tag<string>`x`"),
        "the relational `tag<string>`x`` must survive the plain-JS rewrite (no TS-strip):\n{js}"
    );
    // NEGATIVE: the type-arg-stripped tagged-template form must NOT be emitted (the
    // pre-fix tsx+strip lane produced exactly this corruption).
    assert!(
        !js.contains("tag`x`"),
        "the plain-JS rewrite lane must NOT TS-strip `tag<string>`x`` into `tag`x``:\n{js}"
    );
    // The pair is accepted and routed through the bind_value helper.
    assert!(
        js.contains("$.bind_value(input, tag<string>`x`, (x) => $.set(v, x, true))"),
        "the discriminator pair must emit bind_value with the relational getter:\n{js}"
    );
}

#[test]
fn bind_value_member_of_import_admitted_with_frame() {
    // A MEMBER of an import is an ACCEPTED bind lvalue — official svelte@5.56.3
    // emits the plain member closures `$.bind_value(input, () => store.x,
    // ($$value) => store.x = $$value)` AND the member read opens the component
    // context frame (`$.push($$props, true)` / `$.pop()` + the `$$props` param).
    // Only the BARE import root `bind:value={store}` is rejected (the
    // non-writable-import-root gate; official `constant_binding`).
    let js = emit(
        "<script>import { store } from './s.js'; let c = $state(0);</script>\n<input bind:value={store.x} />\n<button onclick={() => c++}>{c}</button>\n",
        "App.svelte",
    );
    assert!(
        js.contains("$.bind_value(input, () => store.x, ($$value) => store.x = $$value)"),
        "the member-of-import bind must emit the plain member closures:\n{js}"
    );
    assert!(
        js.contains("import { store } from './s.js';"),
        "the import must be hoisted to the module prelude:\n{js}"
    );
    assert!(
        js.contains("$.push($$props, true)") && js.contains("$.pop()"),
        "the imported-member read must open the component context frame:\n{js}"
    );
    assert!(
        js.contains("($$anchor, $$props)"),
        "the frame must bind the $$props parameter:\n{js}"
    );
    // NEGATIVE: the import binding is never a signal — no `$.get(store)`, and the
    // setter is the plain member assignment, never `$.set`.
    assert!(
        !js.contains("$.get(store)"),
        "an import read must stay plain (never `$.get`):\n{js}"
    );
    assert!(
        !js.contains("$.set(store"),
        "an import member setter must stay a plain member write (never `$.set`):\n{js}"
    );
}

#[test]
fn bind_value_bare_import_root_fails_closed_at_the_bind_lvalue_gate() {
    // The BARE import root `bind:value={store}` REJECTS at the bind-lvalue-root
    // gate (an import is a NON-writable root — official `constant_binding`,
    // "Cannot bind to import"), NOT at the script gate: the import itself is
    // admitted to the prelude, the bind target is the refusal.
    assert_fail_closed(
        "<script>import { store } from './s.js'; let c = $state(0);</script>\n<input bind:value={store} />\n<button onclick={() => c++}>{c}</button>\n",
        |s| matches!(s, UnsupportedSvelteRuntimeSurface::Binding { target, .. } if target == "value"),
    );
}
// ── form / value-bearing elements: allowlisted bind hosts whose special content /
//    attr models still fail closed ──────────────────────────────────────────────
//
// `<select>` / `<option>` / `<textarea>` ARE in the finite client-core element
// allowlist (`a` / `button` / `div` / `h1` / `input` / `p` / `video` / `textarea` /
// `select` / `option` / `audio` / `details`) — they were added as 5c `bind:value`
// hosts. So a component using them passes the ELEMENT gate; the refusal MOVES to
// their special content / attr models (a static `value` / `selected` is the
// form-control setter family 5c owns via `bind:value`, NOT a static-attr
// serializer), which fail closed at the ATTR gate. `<datalist>` is NOT allowlisted,
// so it still fails closed at the ELEMENT gate
// (`svelte-runtime-unsupported-element`) on the FIRST out-of-allowlist element.

#[test]
fn select_option_static_value_attr_fails_closed_at_the_form_control_gate() {
    // `<select>`/`<option>` are now in the element allowlist (5c bind hosts), so the
    // refusal MOVES to the static `value` attr on `<option>`: a static `value` is the
    // form-control setter family (5c emits `bind:value`, NOT the static-`value`
    // serializer), so it fails closed via the `DynamicAttribute`/form-control channel.
    // RED if the static `value` attr were silently serialized.
    assert_fail_closed(
        "<script>let c = $state(0);</script>\n<select><option value=\"a\">A</option></select>\n<button onclick={() => c++}>{c}</button>\n",
        |s| matches!(s, UnsupportedSvelteRuntimeSurface::DynamicAttribute { name, .. } if name == "value"),
    );
}

#[test]
fn select_static_value_attr_fails_closed_at_the_form_control_gate() {
    // `<select value="x">` — the static `value` on the now-allowed `<select>` host is
    // the form-control setter family (5c owns `bind:value`, not the static-`value`
    // attr), so it fails closed at the attr gate, NOT the element gate.
    assert_fail_closed(
        "<script>let c = $state(0);</script>\n<select value=\"x\"><option>A</option></select>\n<button onclick={() => c++}>{c}</button>\n",
        |s| matches!(s, UnsupportedSvelteRuntimeSurface::DynamicAttribute { name, .. } if name == "value"),
    );
}

#[test]
fn datalist_element_fails_closed_at_the_element_allowlist() {
    // A `<datalist>` is out of the allowlist — the component fails at the element gate
    // on `<datalist>`.
    assert_fail_closed(
        "<script>let c = $state(0);</script>\n<datalist><option value=\"a\">A</option></datalist>\n<button onclick={() => c++}>{c}</button>\n",
        |s| matches!(s, UnsupportedSvelteRuntimeSurface::Element { tag, .. } if tag == "datalist"),
    );
}

#[test]
fn textarea_static_value_attr_fails_closed_at_the_form_control_gate() {
    // `<textarea>` is now an allowed 5c bind host, so a static `value` attr (the
    // form-control setter family — 5c emits `bind:value`, not the static-`value`
    // serializer) fails closed at the attr gate. The empty content passes the
    // special-content gate; the static `value` is the refusal.
    assert_fail_closed(
        "<script>let c = $state(0);</script>\n<textarea value=\"hi\"></textarea>\n<button onclick={() => c++}>{c}</button>\n",
        |s| matches!(s, UnsupportedSvelteRuntimeSurface::DynamicAttribute { name, .. } if name == "value"),
    );
}

#[test]
fn option_static_selected_attr_fails_closed_at_the_form_control_gate() {
    // A static `selected` on the now-allowed `<option>` is the form-control setter
    // family (`selected` rides the form-control deferral channel alongside
    // `value`/`checked`), so it fails closed at the attr gate. RED if `selected=""`
    // were silently serialized into the cloned template.
    assert_fail_closed(
        "<script>let c = $state(0);</script>\n<select><option selected>A</option></select>\n<button onclick={() => c++}>{c}</button>\n",
        |s| matches!(s, UnsupportedSvelteRuntimeSurface::DynamicAttribute { name, .. } if name == "selected"),
    );
}

// ── static attrs on custom / customized-built-in elements ──────────────────────
//
// A custom element (hyphenated tag) or a customized built-in (`is=`) sets its
// attributes via PROPERTIES at runtime: official omits non-`is` attrs from the
// skeleton and emits `$.set_custom_element_data(node, name, value)`. Verter omits
// the attr from the skeleton (custom-element serializer rule) AND emits no setter
// — the attr silently VANISHES. Fail closed.

#[test]
fn custom_element_static_attr_fails_closed() {
    // F-γ: `<my-widget foo="bar">` → official `$.set_custom_element_data(my_widget,
    // 'foo', 'bar')`. RED: Verter dropped `foo` entirely (no skeleton entry, no
    // setter).
    assert_fail_closed(
        "<script>let c = $state(0);</script>\n<my-widget foo=\"bar\"></my-widget>\n<button onclick={() => c++}>{c}</button>\n",
        |s| matches!(s, UnsupportedSvelteRuntimeSurface::HostOrCustomElement { .. }),
    );
}

#[test]
fn customized_builtin_static_attr_fails_closed() {
    // F-γ: a customized built-in (`is=`) with a non-`is` static attr — official
    // `$.set_custom_element_data(button, 'foo', 'bar')`. Fail closed.
    assert_fail_closed(
        "<script>let c = $state(0);</script>\n<button is=\"my-btn\" foo=\"bar\">x</button>\n<button onclick={() => c++}>{c}</button>\n",
        |s| matches!(s, UnsupportedSvelteRuntimeSurface::HostOrCustomElement { .. }),
    );
}

#[test]
fn customized_builtin_is_only_now_fails_closed_at_the_element_gate() {
    // DEMOTION proof: a customized built-in with ONLY the `is` attr USED to serialize
    // `is="my-btn"` and emit a Main. Under the strict allowlist, ANY element carrying
    // an `is` attribute is rejected at the element gate (`host-custom-element`)
    // BEFORE the attr walk — so an `is`-only `<button>` now fails closed (no Main).
    assert_fail_closed(
        "<script>let c = $state(0);</script>\n<button is=\"my-btn\">x</button>\n<button onclick={() => c++}>{c}</button>\n",
        |s| matches!(s, UnsupportedSvelteRuntimeSurface::HostOrCustomElement { .. }),
    );
}

#[test]
fn component_emits_a_direct_call() {
    // A component reference (a capitalized tag) imported from a `.svelte` module emits a
    // DIRECT `Foo($$anchor, {})` call (the component surface), NOT a `$.get` on the callee
    // (the imported local is a non-reactive value binding).
    // The `$props()` rune forces runes mode (an import-only component is legacy mode, 5i).
    let js = emit_result(
        "<script>import Foo from './Foo.svelte'; let { x } = $props();</script>\n<Foo />\n",
    )
    .expect("a component reference emits a module");
    assert!(
        js.contains("import Foo from './Foo.svelte';"),
        "missing the component import:\n{js}"
    );
    assert!(
        js.contains("Foo($$anchor, {})"),
        "missing the direct component call:\n{js}"
    );
    // NEGATIVE: the imported callee is read as a bare name, NEVER `$.get(Foo)`.
    assert!(
        !js.contains("$.get(Foo)"),
        "the component callee must be a bare name, not $.get:\n{js}"
    );
}

#[test]
fn component_named_import_from_a_barrel_emits_a_direct_call() {
    // Svelte component values are routinely re-exported through plain TS/JS
    // barrels. At runtime a named import is still an immutable live import
    // binding and is therefore a sound static component callee; the shallow
    // compiler must not require the immediate specifier to end in `.svelte`.
    let js = emit_result(
        "<script>import { Child } from './public'; let { label } = $props();</script>\n<Child label={label} />\n",
    )
    .expect("a barrel-imported component emits a module");
    assert!(
        js.contains("import { Child } from './public';"),
        "missing the authored barrel import:\n{js}"
    );
    assert!(
        js.contains("Child($$anchor, {get label()") && js.contains("return $$props.label;"),
        "missing the direct barrel-imported component call:\n{js}"
    );
    assert!(
        !js.contains("$.get(Child)"),
        "an imported component callee is a bare live import read:\n{js}"
    );
}

#[test]
fn component_unbound_callee_fails_closed() {
    // The callee-resolution DISCRIMINATOR: a capitalized component tag whose name
    // resolves to NO admitted `.svelte`-component import is an unsupported component SOURCE
    // — it fails CLOSED, NOT a coincidental bare `Foo($$anchor, {})` call on an unbound
    // global. This is the SAME fixture as `component_emits_a_direct_call` MINUS the import,
    // so the only difference is whether `Foo` resolves to a `ComponentImport` binding — the
    // `!$.get(Foo)` assertion alone is non-discriminating (an unbound global also emits bare
    // `Foo`). The `$props()` rune forces runes mode.
    assert_fail_closed("<script>let { p } = $props();</script>\n<Foo />\n", |s| {
        matches!(
            s,
            UnsupportedSvelteRuntimeSurface::ComponentOrSnippet {
                construct: "component",
                ..
            }
        )
    });
}

#[test]
fn component_dotted_callee_fails_closed() {
    // A DOTTED static component name (`<Foo.Bar/>`) is a namespace/member-component source —
    // an advanced form this vertical does not model. Only a BARE identifier resolving to an
    // admitted `.svelte`-component import is authorized; the whole-name gate fails CLOSED on
    // the dot even though the HEAD segment `Foo` IS an admitted `ComponentImport`. A default
    // `.svelte` import is a component FUNCTION (not a namespace object), so `Foo.Bar` would be
    // a likely-undefined member access — emitting `Foo.Bar($$anchor, …)` is wrong. This is
    // the DISCRIMINATOR vs `component_emits_a_direct_call`: same admitted `Foo` import, but
    // the dotted tag must refuse where the bare `<Foo/>` emits. The `$props()` rune forces
    // runes mode so the fixture reaches the component projection (not the legacy dispatch).
    assert_fail_closed(
        "<script>import Foo from './Foo.svelte'; let { p } = $props();</script>\n<Foo.Bar />\n",
        |s| {
            matches!(
                s,
                UnsupportedSvelteRuntimeSurface::ComponentOrSnippet {
                    construct: "component",
                    ..
                }
            )
        },
    );
}

// ── Component-host binding surfaces: the component invocation host is now SUPPORTED — a
//    component `bind:this` / `bind:prop` / function-pair emits the official
//    `$.bind_this` / getter-setter-pair shapes. Each test is DISCRIMINATING (asserts the
//    exact emitted shape + the absence of the DOM `$.bind_*` helper). ──

#[test]
fn component_bind_this_emits_bind_this_wrapper() {
    // `<Child bind:this={inst}/>` — the COMPONENT host emits `$.bind_this(Child(...), set,
    // get)`, NOT a DOM `$.bind_*` helper.
    let js = emit_result(
        "<script>import Child from './Child.svelte'; let inst = $state();</script>\n<Child bind:this={inst} />\n",
    )
    .expect("a component bind:this emits a module");
    assert!(
        js.contains("$.bind_this(Child("),
        "missing the $.bind_this wrapper:\n{js}"
    );
    // NEGATIVE: a component bind:this is NOT a DOM element `$.bind_this(node)` on a cloned
    // element, and never a `$.bind_value`-style DOM bind.
    assert!(
        !js.contains("$.bind_value"),
        "a component bind:this must not emit a DOM value bind:\n{js}"
    );
}

#[test]
fn component_bind_prop_emits_getter_setter_pair() {
    // `<Child bind:value={val}/>` — the COMPONENT host emits a getter/setter PAIR on the
    // props object (`get value()/set value($$value)` with the `$.set(val, $$value, true)`
    // should-proxy axis), NOT a `$.bind_*` helper.
    let js = emit_result(
        "<script>import Child from './Child.svelte'; let val = $state('');</script>\n<Child bind:value={val} />\n",
    )
    .expect("a component bind:prop emits a module");
    assert!(
        js.contains("get value() {return $.get(val);}")
            && js.contains("set value($$value) {$.set(val, $$value, true);}"),
        "missing the component bind:prop getter/setter pair:\n{js}"
    );
    // NEGATIVE: NOT a DOM `$.bind_value` helper.
    assert!(
        !js.contains("$.bind_value"),
        "a component bind:prop must not emit a DOM value bind:\n{js}"
    );
}

#[test]
fn component_function_binding_emits_bind_get_set_locals() {
    // `<Child bind:x={get, set}/>` — a component FUNCTION binding hoists `var bind_get` /
    // `var bind_set` locals and the prop getter/setter call them.
    let js = emit_result(
        "<script>import Child from './Child.svelte'; let v = $state(0);</script>\n<Child bind:x={() => v, (nv) => v = nv} />\n",
    )
    .expect("a component function binding emits a module");
    assert!(
        js.contains("var bind_get = () => $.get(v);")
            && js.contains("var bind_set = (nv) => $.set(v, nv, true);"),
        "missing the function-pair bind locals:\n{js}"
    );
    assert!(
        js.contains("get x() {return bind_get();}")
            && js.contains("set x($$value) {bind_set($$value);}"),
        "missing the prop getter/setter calling the bind locals:\n{js}"
    );
}

#[test]
fn component_multi_function_binding_emits_distinct_bind_locals() {
    // TWO function-pair binds on ONE component allocate UNIQUE locals: the first pair is
    // `bind_get`/`bind_set`, the SECOND `bind_get_1`/`bind_set_1` (the component-function
    // name uniquing). A shared pair would make BOTH props call the LAST getter/setter — the
    // codegen-correctness bug this guards against.
    let js = emit_result(
        "<script>import Child from './Child.svelte'; let v = $state(0); let w = $state(1);</script>\n<Child bind:value={() => v, (nv) => v = nv} bind:other={() => w, (nw) => w = nw} />\n",
    )
    .expect("two component function bindings emit a module");
    // The first pair drives `value`.
    assert!(
        js.contains("var bind_get = () => $.get(v);")
            && js.contains("get value() {return bind_get();}"),
        "missing the first function-pair locals wired to `value`:\n{js}"
    );
    // The SECOND pair drives `other` with the SUFFIXED `_1` names.
    assert!(
        js.contains("var bind_get_1 = () => $.get(w);")
            && js.contains("var bind_set_1 = (nw) => $.set(w, nw, true);")
            && js.contains("get other() {return bind_get_1();}")
            && js.contains("set other($$value) {bind_set_1($$value);}"),
        "missing the suffixed second function-pair locals wired to `other`:\n{js}"
    );
    // NEGATIVE: the two binds must NOT alias the same local — `other`'s setter is the
    // suffixed `bind_set_1`, NEVER the first pair's `bind_set`.
    assert!(
        !js.contains("set other($$value) {bind_set($$value);}"),
        "the two function binds must not alias the same `bind_set` local:\n{js}"
    );
}

#[test]
fn component_function_binding_renames_past_user_bind_get_collision() {
    // A USER local named `bind_get` must NOT collide with the generated function-pair bind
    // local. The names are minted through the shared scope-aware allocator (seeded with every
    // user binding), so the getter local renames to `bind_get_1` — emitting VALID JS with a
    // SINGLE `bind_get` declaration. A bare counter (the pre-fix path) mints `bind_get`
    // unconditionally, producing `let bind_get …; var bind_get …` = invalid duplicate-binding
    // JS for a valid component. `bind_set` is free, so it keeps its stem (the allocator reserves
    // each stem INDEPENDENTLY, matching official `scope.generate`).
    let js = emit_result(
        "<script>import Child from './Child.svelte'; let bind_get = $state(0); let v = $state(1);</script>\n<Child bind:x={() => v, (nv) => v = nv} />\n",
    )
    .expect("a component function binding with a colliding user local emits a module");
    // The user `bind_get` local is declared (a `let`, distinct from the generated `var`s).
    assert!(
        js.contains("let bind_get = "),
        "missing the user `bind_get` local declaration:\n{js}"
    );
    // The generated getter local RENAMES past the user `bind_get` → `bind_get_1`.
    assert!(
        js.contains("var bind_get_1 = () => $.get(v);")
            && js.contains("get x() {return bind_get_1();}"),
        "the generated getter local must rename to `bind_get_1`:\n{js}"
    );
    // The setter local keeps the free `bind_set` stem.
    assert!(
        js.contains("var bind_set = (nv) => $.set(v, nv, true);")
            && js.contains("set x($$value) {bind_set($$value);}"),
        "the setter local must keep the free `bind_set` stem:\n{js}"
    );
    // DISCRIMINATOR: there must be NO generated `var bind_get` (that would duplicate the user
    // `let bind_get` → invalid JS). The generated local is the suffixed `var bind_get_1`.
    assert!(
        !js.contains("var bind_get = "),
        "the generated bind local must not duplicate the user `bind_get` declaration:\n{js}"
    );
}

// ── Component unit coverage: the `.svelte` default-import subset, the component-family
//    specials, and the COMPONENT-vs-ELEMENT `let:` split. ──

#[test]
fn every_static_import_form_is_admitted_to_the_instance_prelude_slot() {
    // The static-import prelude admits EVERY static import form. The `.svelte`
    // component default stays the component-callee subset; named / aliased /
    // namespace / side-effect / non-`.svelte` default / mixed forms are hoisted to
    // the INSTANCE slot of the module prelude (AFTER `import * as $`), each emitted
    // verbatim in source order.
    let ok = emit_result(
        "<script>import Child from './Child.svelte'; let { p } = $props();</script>\n<Child />\n{p}\n",
    )
    .expect("a default .svelte import is admitted");
    assert!(
        ok.contains("import Child from './Child.svelte';"),
        "the default .svelte import must be hoisted to module scope:\n{ok}"
    );
    for (label, import_stmt, expected) in [
        (
            "named",
            "import { helper } from './helpers.js';",
            "import { helper } from './helpers.js';",
        ),
        (
            "named-alias",
            "import { a as b } from './helpers.js';",
            "import { a as b } from './helpers.js';",
        ),
        (
            "namespace",
            "import * as NS from './ns.js';",
            "import * as NS from './ns.js';",
        ),
        (
            "side-effect",
            "import './setup.js';",
            "import './setup.js';",
        ),
        (
            "default-non-svelte",
            "import helper from './helper.js';",
            "import helper from './helper.js';",
        ),
        (
            "mixed-default-named",
            "import Child, { x } from './Child.svelte';",
            "import Child, { x } from './Child.svelte';",
        ),
    ] {
        let src = format!(
            "<script>{import_stmt} let __r = $state(0);</script>\n<button onclick={{() => __r++}}>{{__r}}</button>\n"
        );
        let js = emit_result(&src)
            .unwrap_or_else(|e| panic!("[{label}] a static import form must be admitted: {e:?}"));
        // The import lands in the INSTANCE slot: after the runtime namespace import.
        let ns_at = js
            .find("import * as $ from 'svelte/internal/client';")
            .unwrap_or_else(|| panic!("[{label}] missing the runtime namespace:\n{js}"));
        let user_at = js
            .find(expected)
            .unwrap_or_else(|| panic!("[{label}] missing the hoisted user import:\n{js}"));
        assert!(
            user_at > ns_at,
            "[{label}] an instance import must emit AFTER the runtime namespace:\n{js}"
        );
        // NEGATIVE: the admitted form must not leak the old script-import refusal
        // diagnostic anywhere (it compiled), and the import is module-scope — before
        // the component function.
        assert!(
            user_at < js.find("export default function").unwrap(),
            "[{label}] the user import must be module-scope (above the component fn):\n{js}"
        );
    }
}

// ── static-import malformed/adjacent siblings — every accepted import/bind/read
//    form's siblings either fail closed or take their own correct path ──

#[test]
fn import_assert_attribute_keyword_rejects_with_official_parse_parity() {
    // The deprecated `assert { type: 'json' }` attribute keyword is an OFFICIAL
    // acorn parse-REJECT in a plain script (`js_parse_error` "Unexpected token",
    // oracle-probed; acorn has no `assert` clause) — only `with { … }` is
    // admitted+preserved. The body probe carries the EXACT official code (OXC itself
    // is assert-lenient, so the probe discriminates the keyword structurally);
    // Verter must not emit — and must not silently normalize `assert` to `with`.
    for (label, src) in [
        (
            "instance slot",
            "<script>import data from './d.json' assert { type: 'json' }; let c = $state(0);</script>\n<p>{data}</p>\n<button onclick={() => c++}>{c}</button>\n",
        ),
        (
            "module slot",
            "<script module>import data from './d.json' assert { type: 'json' };</script>\n<script>let c = $state(0);</script>\n<button onclick={() => c++}>{c}</button>\n",
        ),
    ] {
        let err =
            emit_result(src).expect_err("an `assert { … }` import attribute must fail closed");
        assert!(
            matches!(
                &err,
                ClientCompileError::OfficialReject(r)
                    if r.rule == CoreOfficialValidationRule::ScriptBodyParse
                        && r.official_code == "js_parse_error"
            ),
            "[{label}] expected the exact js_parse_error parse-parity reject for the \
             `assert` keyword, got {err:?}"
        );
    }
    // CONTROL: a `lang=\"ts\"` script parses `assert` fine (official ACCEPTS it there,
    // oracle-probed — the TS grammar keeps the legacy clause), so the Js-grammar
    // parse-parity rule must NOT fire; the component stays owned by the
    // TypeScript-script refusal (fail-closed, non-official-code channel).
    let js = emit(
        "<script lang=\"ts\">import data from './d.json' assert { type: 'json' }; let c = $state(0);</script>\n<p>{data}</p>\n<button onclick={() => c++}>{c}</button>\n",
        "App.svelte",
    );
    assert!(
        js.contains("import data from './d.json' with { type: 'json' }"),
        "a TypeScript import assertion must normalize to `with`:\n{js}"
    );
    assert!(
        !js.contains(" assert {"),
        "legacy assertion syntax leaked:\n{js}"
    );
    assert!(parses_as_js(&js), "emitted module must parse as JS:\n{js}");
}

#[test]
fn type_only_and_phase_imports_reject_with_official_parse_parity() {
    // A TypeScript TYPE-ONLY import in a PLAIN script (decl-level or
    // per-specifier) and an import PHASE (`import defer * as ns`) are official
    // acorn PARSE errors (`js_parse_error`, oracle-probed) — Verter's
    // parse-parity gate rejects each with the EXACT official code BEFORE the
    // import classifier runs (the classifier's type-only / phase arms stay a
    // defense-in-depth stop behind it). Never a Main, never an emitted
    // `import type` / phase statement.
    for (label, import_stmt) in [
        ("type-only-decl", "import type { T } from './t.js';"),
        ("type-only-specifier", "import { type T, x } from './t.js';"),
    ] {
        let src = format!(
            "<script>{import_stmt} let c = $state(0);</script>\n<button onclick={{() => c++}}>{{c}}</button>\n"
        );
        let err = emit_result(&src).expect_err("a type-only import must not compile to a Main");
        assert!(
            matches!(&err, ClientCompileError::OfficialReject(r) if r.official_code == "js_parse_error"),
            "[{label}] expected the js_parse_error parse-parity reject, got {err:?}"
        );
    }
    // An import PHASE (`import defer * as ns`) parses under the TS-lenient shared
    // reparse (OXC supports the import-phase proposal), so the parse-parity gate
    // does not see it — the
    // import classifier's phase arm refuses it fail-closed (official also rejects,
    // `js_parse_error`; the exact-code parity for phase syntax is the parse-parity
    // surface's breadth, not the import prelude's).
    assert_fail_closed(
        "<script>import defer * as NS from './m.js'; let c = $state(0);</script>\n<button onclick={() => c++}>{c}</button>\n",
        |s| {
            matches!(
                s,
                UnsupportedSvelteRuntimeSurface::ScriptImport {
                    construct: "import phase",
                    ..
                }
            )
        },
    );
}

#[test]
fn import_with_attribute_is_preserved_verbatim() {
    // The accepted sibling: `with { type: 'json' }` is official-accepted and MUST
    // survive onto the emitted import statement (dropping it changes module-load
    // semantics for JSON/CSS modules).
    let js = emit(
        "<script>import data from './d.json' with { type: 'json' }; let c = $state(0);</script>\n<p>{data}</p>\n<button onclick={() => c++}>{c}</button>\n",
        "App.svelte",
    );
    assert!(
        js.contains("import data from './d.json' with { type: 'json' };"),
        "the `with` import attributes must be preserved verbatim:\n{js}"
    );
    // NEGATIVE: never rewritten to the deprecated `assert` spelling.
    assert!(
        !js.contains("assert {"),
        "the `with` clause must not be emitted as `assert`:\n{js}"
    );
}

#[test]
fn dynamic_import_expression_is_not_a_static_import_and_keeps_its_own_path() {
    // A DYNAMIC `import('./x.js')` expression is NOT a static import declaration —
    // it must not route through the static-import prelude. It rides the unchanged
    // handler-shape path (a call-bearing arrow body is that surface's own
    // fail-closed breadth today), and the refusal is NOT a script-import /
    // module-item diagnostic.
    let err = emit_result(
        "<script>let c = $state(0);</script>\n<button onclick={() => import('./x.js')}>{c}</button>\n",
    )
    .expect_err("a dynamic import() handler body is not yet an emittable handler shape");
    match err {
        ClientCompileError::Unsupported(surface) => {
            assert!(
                !matches!(
                    surface,
                    UnsupportedSvelteRuntimeSurface::ScriptImport { .. }
                        | UnsupportedSvelteRuntimeSurface::ModuleScriptItem { .. }
                ),
                "a dynamic import() must not classify as a static script import: {surface:?}"
            );
        }
        other => panic!("expected an unsupported-surface refusal, got {other:?}"),
    }
}

#[test]
fn duplicate_same_source_imports_stay_two_statements() {
    // Official does NOT merge two imports from the same source — the prelude keeps
    // TWO statements in source order.
    let js = emit(
        "<script>import { a } from './m.js'; import { b } from './m.js'; let c = $state(0);</script>\n<p>{a} {b}</p>\n<button onclick={() => c++}>{c}</button>\n",
        "App.svelte",
    );
    assert!(
        js.contains("import { a } from './m.js';") && js.contains("import { b } from './m.js';"),
        "both same-source imports must emit:\n{js}"
    );
    // NEGATIVE: never merged into one statement.
    assert!(
        !js.contains("import { a, b }"),
        "same-source imports must stay UNMERGED (two statements):\n{js}"
    );
}

#[test]
fn import_redeclaration_rejects_with_official_parse_parity() {
    // An import local that COLLIDES with another top-level binding of the same
    // script is an official acorn PARSE error ("Identifier 'x' has already been
    // declared", `js_parse_error`, oracle-confirmed vs the pinned compiler) — the
    // module-scope duplicate-binding early error. Every collision family must
    // reject with the EXACT official code, never compile to a Main:
    //   - import + `let` (default and named locals),
    //   - duplicate import locals across two declarations,
    //   - import + `var` (an import binds lexically, so the `var`/`var` exemption
    //     does not apply),
    //   - import + `function` (a module-scope function declaration binds lexically).
    for (label, script) in [
        (
            "default-import-then-let",
            "import x from './m.js'; let x = $state(0);",
        ),
        (
            "named-import-then-let",
            "import { x } from './m.js'; let x = $state(0);",
        ),
        (
            "duplicate-import-locals",
            "import { x } from './a.js'; import { x } from './b.js'; let s = $state(0);",
        ),
        (
            "import-then-var",
            "import { x } from './m.js'; var x = 1; let s = $state(0);",
        ),
        (
            "import-then-function",
            "import { x } from './m.js'; function x() {} let s = $state(0);",
        ),
    ] {
        let src = format!("<script>{script}</script>\n<p>hi</p>\n");
        let err =
            emit_result(&src).expect_err("an import redeclaration must not compile to a Main");
        assert!(
            matches!(&err, ClientCompileError::OfficialReject(r) if r.official_code == "js_parse_error"),
            "[{label}] expected the js_parse_error parse-parity reject, got {err:?}"
        );
    }
    // The MODULE slot rejects identically — each script body runs its own
    // duplicate-binding probe.
    let err = emit_result(
        "<script module>import { x } from './a.js'; import { x } from './b.js';</script>\n<script>let c = $state(0);</script>\n<button onclick={() => c++}>{c}</button>\n",
    )
    .expect_err("a module-slot import redeclaration must not compile to a Main");
    assert!(
        matches!(&err, ClientCompileError::OfficialReject(r) if r.official_code == "js_parse_error"),
        "a module-slot duplicate import local is the same js_parse_error reject, got {err:?}"
    );
    // CONTROL (no false-reject): a DISTINCT import local + `let` name compiles, and
    // the import statement survives onto the module prelude.
    let js = emit(
        "<script>import { x } from './m.js'; let y = $state(0);</script>\n<p>hi</p>\n",
        "App.svelte",
    );
    assert!(
        js.contains("import { x } from './m.js';"),
        "the distinct-name control must keep compiling with its import:\n{js}"
    );
}

#[test]
fn cross_script_redeclaration_rejects_with_exact_official_codes() {
    // A binding declared in BOTH `<script>` slots — the per-body parse probe cannot
    // see it (each body parses clean alone), so it is the component-level
    // DeclarationDuplicate scan's. Official svelte@5.56.3 rejects each with an EXACT
    // code (oracle-probed): an instance value declaration over a MODULE import is
    // `declaration_duplicate_module_import`; an instance import colliding with a
    // module-slot binding is `declaration_duplicate` (the binder hoists the instance
    // import into the module scope). RED before the fix: every one of these compiled
    // to a Main (the cross-script fail-open).
    for (label, source, expected_code) in [
        (
            "module-default-import + instance-let-state",
            "<script module>import x from './m.js';</script>\n<script>let x = $state(0);</script>\n<p>hi</p>\n",
            "declaration_duplicate_module_import",
        ),
        (
            "module-named-import + instance-import",
            "<script module>import { x } from './m.js';</script>\n<script>import { x } from './n.js';\nlet s = $state(0);</script>\n<p>{s}</p>\n",
            "declaration_duplicate",
        ),
        (
            "module-named-import + instance-let-state",
            "<script module>import { x } from './m.js';</script>\n<script>let x = $state(0);</script>\n<p>hi</p>\n",
            "declaration_duplicate_module_import",
        ),
    ] {
        let err = emit_result(source)
            .expect_err("a cross-script redeclaration must not compile to a Main");
        assert!(
            matches!(
                &err,
                ClientCompileError::OfficialReject(r)
                    if r.rule == CoreOfficialValidationRule::DeclarationDuplicate
                        && r.official_code == expected_code
            ),
            "[{label}] expected the exact {expected_code} cross-script reject, got {err:?}"
        );
    }
    // SAME-body regression: a within-body duplicate stays the parse-phase
    // `js_parse_error` (the body probe), never re-attributed to the cross-script scan.
    let err = emit_result(
        "<script>import { x } from './a.js'; import { x } from './b.js'; let s = $state(0);</script>\n<p>hi</p>\n",
    )
    .expect_err("a same-body duplicate must not compile to a Main");
    assert!(
        matches!(
            &err,
            ClientCompileError::OfficialReject(r)
                if r.rule == CoreOfficialValidationRule::ScriptBodyParse
                    && r.official_code == "js_parse_error"
        ),
        "a same-body duplicate must stay the js_parse_error parse-parity reject, got {err:?}"
    );
    // CONTROLS (no over-reject; oracle-probed ACCEPTs):
    // (a) distinct names across the two slots keep compiling — the module import emits.
    let js = emit(
        "<script module>import { x } from './m.js';</script>\n<script>let y = $state(0);</script>\n<button onclick={() => y++}>{y}</button>\n",
        "App.svelte",
    );
    assert!(
        js.contains("import { x } from './m.js';"),
        "the distinct-name cross-script control must keep compiling with its module import:\n{js}"
    );
    // (b) cross-script `var`/`var` and a module `var` + instance import are official-
    // ACCEPTED (a prior `var` never trips the binder's duplicate check) — they must
    // NOT reject as DeclarationDuplicate. (A module `var` statement itself stays
    // fail-closed as an unsupported module-script item — an honest deferral, so the
    // control asserts the refusal CHANNEL, not an emission.)
    for (label, source) in [
        (
            "var + var",
            "<script module>var x = 1;</script>\n<script>var x = 2;\nlet s = $state(0);</script>\n<p>{s}</p>\n",
        ),
        (
            "module-var + instance-import",
            "<script module>var x = 1;</script>\n<script>import { x } from './b.js';\nlet s = $state(0);</script>\n<p>{s}</p>\n",
        ),
    ] {
        let err = emit_result(source).expect_err("a module `var` item stays fail-closed");
        assert!(
            !matches!(
                &err,
                ClientCompileError::OfficialReject(r)
                    if r.rule == CoreOfficialValidationRule::DeclarationDuplicate
            ),
            "[{label}] an official-accepted `var` combination must not be over-rejected \
             as DeclarationDuplicate, got {err:?}"
        );
    }
}

#[test]
fn import_reassignment_rejects_constant_assignment() {
    // A handler ASSIGNMENT to an import binding is the official
    // `constant_assignment` compile error ("Cannot assign to import") — carried
    // through the rewriter's official-reject channel, never a raw plain write.
    for (label, handler) in [("assign", "() => x = 1"), ("update", "() => x++")] {
        // A DIRECT (non-delegated) event routes the arrow body through the shared
        // rewriter — the write refusal is the rewriter's, not the delegated-shape
        // gate's (which admits only `$state`-write arrows and would mask it).
        let err = emit_result(&format!(
            "<script>import {{ x }} from './m.js'; let c = $state(0);</script>\n<button onmouseenter={{{handler}}} onclick={{() => c++}}>{{c}}</button>\n"
        ))
        .expect_err("a write to an import binding must fail closed");
        let ClientCompileError::OfficialReject(rejection) = err else {
            panic!("[{label}] expected the constant_assignment official reject, got {err:?}");
        };
        assert_eq!(
            rejection.official_code, "constant_assignment",
            "[{label}] the exact official code"
        );
    }
    // A MODULE-slot import write from an instance handler rejects identically (the
    // import resolves up the lexical chain).
    let err = emit_result(
        "<script module>import { m } from './base.js';</script>\n<script>let c = $state(0);</script>\n<button onmouseenter={() => m = 1} onclick={() => c++}>{c}</button>\n",
    )
    .expect_err("a write to a module-slot import must fail closed");
    assert!(
        matches!(&err, ClientCompileError::OfficialReject(r) if r.official_code == "constant_assignment"),
        "a module-import write is the same constant_assignment reject, got {err:?}"
    );
}

#[test]
fn import_member_write_in_handler_is_a_plain_member_write_with_frame() {
    // The accepted write sibling: a MEMBER write rooted at an import (`x.k = c`) is
    // a plain member mutation — official accepts it (the import binding itself is
    // untouched) and the member access opens the context frame.
    let js = emit(
        "<script>import { x } from './m.js'; let c = $state(0);</script>\n<button onmouseenter={() => x.k = c} onclick={() => c++}>{c}</button>\n",
        "App.svelte",
    );
    assert!(
        js.contains("$.event('mouseenter', button, () => x.k = $.get(c))"),
        "the member write stays plain with the signal RHS rewritten (the official \
         direct-event form):\n{js}"
    );
    assert!(
        js.contains("$.push($$props, true)"),
        "the imported-member access must open the context frame:\n{js}"
    );
}

#[test]
fn bare_import_read_is_live_and_frame_free() {
    // A BARE imported-ident read `{x}` is LIVE — it joins the region's
    // `$.template_effect`, read PLAIN — and does NOT open the context frame
    // (official: only a member/call rooted at an import frames).
    let js = emit(
        "<script>import { x } from './m.js'; let c = $state(0);</script>\n<p>{x}</p>\n<button onclick={() => c++}>{c}</button>\n",
        "App.svelte",
    );
    assert!(
        js.contains("$.set_text(text, x)"),
        "the bare import read must be a live plain read inside the template effect:\n{js}"
    );
    assert!(
        js.contains("$.template_effect"),
        "the import read must join a template effect (never static-folded):\n{js}"
    );
    // NEGATIVES: never `$.get`, never a static `textContent` fold, and NO frame.
    assert!(
        !js.contains("$.get(x)"),
        "an import read must stay plain (never `$.get`):\n{js}"
    );
    assert!(
        !js.contains("textContent"),
        "an import read must not static-fold:\n{js}"
    );
    assert!(
        !js.contains("$.push"),
        "a bare import read must NOT open the context frame:\n{js}"
    );
}

#[test]
fn instance_namespace_member_read_frames_and_stays_plain() {
    // An INSTANCE-slot namespace MEMBER read `{NS.z}` is live + plain AND opens the
    // context frame (`$.push($$props, true)` / `$.pop()` + the `$$props` param).
    let js = emit(
        "<script>import * as NS from './m.js'; let c = $state(0);</script>\n<p>{NS.z}</p>\n<button onclick={() => c++}>{c}</button>\n",
        "App.svelte",
    );
    assert!(
        js.contains("$.set_text(text, NS.z)"),
        "the member read must stay the plain member expression:\n{js}"
    );
    assert!(
        js.contains("$.push($$props, true)") && js.contains("$.pop()"),
        "the imported-member read must open the context frame:\n{js}"
    );
}

#[test]
fn module_namespace_member_read_frames_like_the_instance_slot() {
    // The MODULE-slot twin: `<script module>import * as NS …</script>` + `{NS.z}`
    // frames identically (module imports are unsafe roots for the shared
    // `needs_context` analysis, resolving up the lexical chain).
    let js = emit(
        "<script module>import * as NS from './m.js';</script>\n<script>let c = $state(0);</script>\n<p>{NS.z}</p>\n<button onclick={() => c++}>{c}</button>\n",
        "App.svelte",
    );
    assert!(
        js.contains("$.set_text(text, NS.z)") && js.contains("$.push($$props, true)"),
        "the module-slot member read must frame like the instance slot:\n{js}"
    );
    // The module import emits BEFORE the runtime namespace (the module slot).
    let module_at = js.find("import * as NS from './m.js';").unwrap();
    let ns_at = js
        .find("import * as $ from 'svelte/internal/client';")
        .unwrap();
    assert!(
        module_at < ns_at,
        "a module-slot import must emit BEFORE the runtime namespace:\n{js}"
    );
}

#[test]
fn non_static_member_chains_on_imports_stay_fail_closed() {
    // The narrow member admit covers STATIC member chains rooted at an import ONLY.
    // A computed member, an optional chain, and a member rooted at a PLAIN local
    // all stay the fail-closed complex-interpolation breadth — the import widening
    // must not leak into the general member-interpolation surface.
    for (label, interp) in [
        ("computed", "{NS['z']}"),
        ("optional", "{NS?.z}"),
        ("call", "{NS.z()}"),
    ] {
        let src = format!(
            "<script>import * as NS from './m.js'; let c = $state(0);</script>\n<p>{interp}</p>\n<button onclick={{() => c++}}>{{c}}</button>\n"
        );
        assert_fail_closed_labeled(label, &src, |s| {
            matches!(
                s,
                UnsupportedSvelteRuntimeSurface::ComplexInterpolation { .. }
            )
        });
    }
    // A static member rooted at a PLAIN LOCAL is untouched by the import widening.
    assert_fail_closed(
        "<script>let d = 1; let c = $state(0);</script>\n<p>{d.x}</p>\n<button onclick={() => c++}>{c}</button>\n",
        |s| {
            matches!(
                s,
                UnsupportedSvelteRuntimeSurface::ComplexInterpolation { .. }
                    | UnsupportedSvelteRuntimeSurface::InstanceScriptItem { .. }
            )
        },
    );
}

#[test]
fn component_prop_value_from_import_emits_the_getter_form() {
    // A component-prop value reading an IMPORT (`b={x}`) `has_state` (imports are
    // live bindings, not statically known), so official emits the GETTER accessor
    // `get b() { return x; }` — never the plain init `b: x` (oracle-verified
    // against svelte@5.56.3).
    let js = emit(
        "<script>import Child from './Child.svelte'; import { x } from './m.js'; let c = $state(0);</script>\n<Child b={x} />\n<button onclick={() => c++}>{c}</button>\n",
        "App.svelte",
    );
    assert!(
        js.contains("get b() {") && js.contains("return x;"),
        "an import-valued component prop must emit the getter accessor:\n{js}"
    );
    assert!(
        !js.contains("b: x"),
        "an import-valued component prop must NOT emit the plain init form:\n{js}"
    );
}

#[test]
fn dynamic_attr_from_import_joins_the_template_effect() {
    // `disabled={x}` from an import is REACTIVE (imports are live bindings): the
    // property write joins the `$.template_effect`, read plain — never a one-shot
    // init, never `$.get` (oracle-verified against svelte@5.56.3).
    let js = emit(
        "<script>import { x } from './m.js'; let c = $state(0);</script>\n<button disabled={x} onclick={() => c++}>{c}</button>\n",
        "App.svelte",
    );
    assert!(
        js.contains("button.disabled = x"),
        "the import-valued property write must read plain:\n{js}"
    );
    let effect_at = js.find("$.template_effect").unwrap_or(usize::MAX);
    let write_at = js.find("button.disabled = x").unwrap_or(0);
    assert!(
        effect_at < write_at,
        "the import-valued property write must join the template effect:\n{js}"
    );
    assert!(
        !js.contains("$.get(x)"),
        "an import read must stay plain (never `$.get`):\n{js}"
    );
}

#[test]
fn svelte_component_special_emits_dollar_component() {
    // `<svelte:component this={comp}>` (a DYNAMIC component) emits the 3-arg
    // `$.component(node, () => $$props.comp, ($$anchor, $$component) => { $$component(...) })`.
    let js = emit_result(
        "<script>let { comp } = $props();</script>\n<svelte:component this={comp} label=\"hi\" />\n",
    )
    .expect("svelte:component emits a module");
    assert!(
        js.contains("$.component(node, () => $$props.comp, ($$anchor, $$component) =>"),
        "missing the $.component(node, () => this, callback) shape:\n{js}"
    );
    assert!(
        js.contains("$$component($$anchor, {label: 'hi'})"),
        "missing the inner $$component call with the props:\n{js}"
    );
}

#[test]
fn svelte_component_special_with_imported_default_uses_bare_callee() {
    // The DYNAMIC-COMPONENT-VALUE half of the 5f-a `.svelte`-default-import subset: a `.svelte`
    // DEFAULT import (`import Child from './Child.svelte'`) consumed as the `<svelte:component
    // this={Child}>` selector. The import is admitted to the prelude REGARDLESS of being used as a
    // dynamic value (not a static `<Child/>` callee), and the `this` expression resolves the
    // non-reactive `ComponentImport` binding to the BARE local — `$.component(node, () => Child,
    // …)`, NEVER `$.get(Child)` / `() => $$props.Child`. The `$props()` rune forces runes mode (an
    // import-only component is legacy mode, 5i).
    let js = emit_result(
        "<script>import Child from './Child.svelte'; let { label } = $props();</script>\n<svelte:component this={Child} {label} />\n",
    )
    .expect("svelte:component with an imported default emits a module");
    // (a) The `.svelte` default import is ADMITTED to the module prelude.
    assert!(
        js.contains("import Child from './Child.svelte';"),
        "missing the admitted `.svelte` default import in the prelude:\n{js}"
    );
    // (b) The imported local drives the dynamic component value as a BARE name.
    assert!(
        js.contains("$.component(node, () => Child, ($$anchor, $$component) =>"),
        "missing the bare-import dynamic component value `() => Child`:\n{js}"
    );
    // NEGATIVE: the imported callee is a non-reactive value binding — never a `$.get` read and
    // never routed through `$$props` (which is what a PROP-sourced `this={comp}` would emit).
    assert!(
        !js.contains("$.get(Child)"),
        "the imported dynamic component value must be a bare name, not $.get:\n{js}"
    );
    assert!(
        !js.contains("() => $$props.Child"),
        "the imported dynamic component value must not route through $$props:\n{js}"
    );
    // CONTRAST: the threaded prop `label` DOES route through `$$props.label` — proving the
    // rewriter discriminates the import binding (bare) from a reactive prop read (so the bare
    // `Child` is the ComponentImport binding-kind decision, not an everything-emits-bare accident).
    assert!(
        js.contains("$$props.label"),
        "the threaded prop must route through $$props (the binding-kind contrast):\n{js}"
    );
}

#[test]
fn svelte_self_special_emits_a_recursive_call() {
    // `<svelte:self>` emits a recursive call through the component's COMPILE-NAME (the
    // filename-derived `App` here), NOT a `$.component` (it is a static self-reference).
    let js = emit_result(
        "<script>let { depth } = $props();</script>\n{#if depth > 0}<svelte:self depth={depth - 1} />{/if}\n",
    )
    .expect("svelte:self emits a module");
    // The fixture compiles under `App.svelte` (the test harness filename) → callee `App`.
    assert!(
        js.contains("App(node"),
        "missing the recursive svelte:self call through the compile-name:\n{js}"
    );
    // NEGATIVE: svelte:self is a STATIC self-reference, NOT a dynamic `$.component`.
    assert!(
        !js.contains("$.component("),
        "svelte:self must not route through $.component:\n{js}"
    );
}

#[test]
fn render_spread_argument_fails_closed_for_every_callee() {
    // Official `svelte@5.56.3` HARD-ERRORS on a SPREAD argument in a `{@render …}` tag
    // (`render_tag_invalid_spread_argument`: "cannot use spread arguments in {@render
    // ...} tags"). Verter must FAIL CLOSED with the typed component/snippet refusal —
    // never silently DROP the spread and emit a wrong-arity `$.snippet(node, () => row)`
    // call. Covers a PROP callee, a LOCAL-`{#snippet}` callee, and a DYNAMIC (optional-
    // call) callee: every callee shape over-accepted the spread before this fix.
    for (label, src) in [
        (
            "prop_callee",
            "<script>let { row, xs } = $props();</script>\n{@render row(...xs)}\n",
        ),
        (
            "local_snippet_callee",
            "<script>let { xs } = $props();</script>\n{#snippet row()}<span>x</span>{/snippet}\n{@render row(...xs)}\n",
        ),
        (
            "dynamic_callee",
            "<script>let { row, xs } = $props();</script>\n{@render row?.(...xs)}\n",
        ),
    ] {
        assert_fail_closed_labeled(label, src, |s| {
            matches!(
                s,
                UnsupportedSvelteRuntimeSurface::ComponentOrSnippet { construct, .. }
                    if *construct == "{@render} spread argument"
            )
        });
    }
}

#[test]
fn render_non_spread_argument_still_emits_a_snippet_call() {
    // The spread refusal is NARROWLY scoped to a SPREAD argument: a NON-spread render
    // arg (`{@render row(item)}`) must STILL emit the `$.snippet(node, callee, () => …)`
    // call carrying its argument thunk, never fail closed.
    let js = emit(
        "<script>let { row, item } = $props();</script>\n{@render row(item)}\n",
        "App.svelte",
    );
    assert!(
        js.contains("$.snippet("),
        "a NON-spread render argument must still emit the $.snippet call:\n{js}"
    );
    // NEGATIVE: the argument thunk survives as the PRECISE `() => $$props.item` thunk —
    // not merely an incidental `item` substring of the `$props()` destructure — proving the
    // spread refusal did not collapse the non-spread arg path.
    assert!(
        js.contains("() => $$props.item"),
        "the non-spread render argument thunk `() => $$props.item` must survive:\n{js}"
    );
}

#[test]
fn render_parenthesized_whole_call_spread_fails_closed() {
    // The render-spread refusal is closed over OUTER author parentheses wrapping the WHOLE
    // call: official `svelte@5.56.3` HARD-ERRORS on the spread
    // (`render_tag_invalid_spread_argument`) no matter how many parens wrap the call, so a
    // parenthesized whole call must FAIL CLOSED exactly like the bare form — never peel to a
    // non-call node and silently DROP the spread into a wrong-arity `$.snippet(node, () =>
    // row)` emit. Covers a single paren, nested parens, a parenthesized OPTIONAL call, and a
    // parenthesized LOCAL-`{#snippet}` callee.
    for (label, src) in [
        (
            "paren_whole_call",
            "<script>let { row, xs } = $props();</script>\n{@render (row(...xs))}\n",
        ),
        (
            "double_paren_whole_call",
            "<script>let { row, xs } = $props();</script>\n{@render ((row(...xs)))}\n",
        ),
        (
            "paren_optional_whole_call",
            "<script>let { row, xs } = $props();</script>\n{@render (row?.(...xs))}\n",
        ),
        (
            "paren_local_snippet",
            "<script>let { xs } = $props();</script>\n{#snippet row()}<span>x</span>{/snippet}\n{@render (row(...xs))}\n",
        ),
    ] {
        assert_fail_closed_labeled(label, src, |s| {
            matches!(
                s,
                UnsupportedSvelteRuntimeSurface::ComponentOrSnippet { construct, .. }
                    if *construct == "{@render} spread argument"
            )
        });
    }
}

#[test]
fn render_array_internal_spread_argument_still_emits() {
    // NARROWNESS CONTROL: an ARRAY-INTERNAL spread (`{@render row([...xs])}`) is a normal
    // array-expression argument, NOT a call-argument spread — official ACCEPTS it. It must
    // STILL emit the `$.snippet` call; peeling outer author parens for the whole-call-spread
    // refusal must not over-refuse this accepted shape. The spread argument is
    // `has_call`-bearing (official `SpreadElement` analysis), so it rides the memoized
    // `let $0 = $.derived(() => [...$$props.xs]);` hoist and the `() => $.get($0)` thunk —
    // the DYNAMIC-callee `$.snippet` form memoizes exactly like the static call.
    let js = emit(
        "<script>let { row, xs } = $props();</script>\n{@render row([...xs])}\n",
        "App.svelte",
    );
    assert!(
        js.contains("$.snippet("),
        "an array-internal spread render arg must still emit the $.snippet call:\n{js}"
    );
    assert!(
        js.contains("let $0 = $.derived(() => ([...$$props.xs]));"),
        "the array-internal spread must memoize into the derived hoist:\n{js}"
    );
    assert!(
        js.contains("$.snippet(node, () => $$props.row, () => $.get($0));"),
        "the $.snippet call must read the memoized $.get thunk:\n{js}"
    );
    // NEGATIVE: never the un-memoized inline spread thunk.
    assert!(
        !js.contains("$.snippet(node, () => $$props.row, () => [...$$props.xs])"),
        "the spread arg must not stay an un-memoized inline thunk:\n{js}"
    );
}

#[test]
fn svelte_self_root_placement_fails_closed() {
    // Official `svelte@5.56.3` HARD-ERRORS on a `<svelte:self>` with NO allowed enclosing
    // context (`svelte_self_invalid_placement`: it may only exist inside {#if}/{#each}/
    // {#snippet} blocks or slots passed to components). A ROOT `<svelte:self>` — bare OR
    // `bind:this` — must FAIL CLOSED with the typed component/snippet refusal, never emit
    // the recursive `App(node, {})` / `$.bind_this(App(node, {}), …)` self-call.
    for (label, src) in [
        (
            "root",
            "<script>let { depth } = $props();</script>\n<svelte:self />\n",
        ),
        (
            "root_bind_this",
            "<script>let { depth } = $props(); let x;</script>\n<svelte:self bind:this={x} />\n",
        ),
    ] {
        assert_fail_closed_labeled(label, src, |s| {
            matches!(
                s,
                UnsupportedSvelteRuntimeSurface::ComponentOrSnippet { construct, .. }
                    if *construct == "svelte:self at invalid placement"
            )
        });
    }
}

#[test]
fn svelte_self_inside_each_block_still_emits() {
    // The placement gate refuses ONLY the no-valid-context case: a `<svelte:self>`
    // validly placed inside an `{#each}` block (an allowed enclosing context, exercised
    // alongside the existing `{#if}` positive control) must STILL emit the recursive
    // self-call — the gate's valid-ancestor propagation must not over-reject a block body.
    let js = emit(
        "<script>let { items } = $props();</script>\n{#each items as item}<svelte:self />{/each}\n",
        "App.svelte",
    );
    assert!(
        js.contains("App("),
        "a svelte:self inside an {{#each}} block must still emit the recursive call:\n{js}"
    );
    // NEGATIVE: still a STATIC self-reference, never a dynamic `$.component`.
    assert!(
        !js.contains("$.component("),
        "an in-block svelte:self must not route through $.component:\n{js}"
    );
}

#[test]
fn component_let_directive_emits_a_slot_prop_derived() {
    // A COMPONENT `let:item` is the slot-prop surface: the default slot becomes a
    // `$$slots.default` callback prepending `const item = $.derived(() => $$slotProps.item)`,
    // and `children` becomes the `$.invalid_default_snippet` sentinel.
    let js = emit_result(
        "<script>import Child from './Child.svelte'; let { p } = $props();</script>\n<Child let:item>{item}</Child>\n",
    )
    .expect("a component let: emits a module");
    assert!(
        js.contains("const item = $.derived(() => $$slotProps.item)"),
        "missing the let: slot-prop derived:\n{js}"
    );
    assert!(
        js.contains("children: $.invalid_default_snippet"),
        "missing the invalid_default_snippet sentinel:\n{js}"
    );
}

#[test]
fn element_let_directive_still_fails_closed() {
    // A `let:` directive on a PLAIN ELEMENT is invalid Svelte (the slot-prop surface is
    // COMPONENT/fragment-only). The element-context `let:` MUST stay fail-closed — the
    // component `let:` path is the component-attr slot-prop classifier, NOT the element
    // refusal.
    assert_fail_closed(
        "<script>let __r = $state(0);</script>\n<div let:item>{__r}</div>\n",
        |s| {
            matches!(
                s,
                UnsupportedSvelteRuntimeSurface::ComponentOrSnippet {
                    construct: "let-directive",
                    ..
                }
            )
        },
    );
}

#[test]
fn component_let_alias_directive_emits_an_aliased_slot_prop_derived() {
    // An ALIASED component `let:item={value}` renames the slot prop `item` to the local
    // `value`: the default-slot callback prepends `const value = $.derived(() =>
    // $$slotProps.item)` (key `item`, local `value`), and a read `{value}` resolves to it.
    let js = emit_result(
        "<script>import Child from './Child.svelte'; let { p } = $props();</script>\n<Child let:item={value}>{value}</Child>\n",
    )
    .expect("an aliased component let: emits a module");
    assert!(
        js.contains("const value = $.derived(() => $$slotProps.item)"),
        "missing the aliased let: slot-prop derived (local `value`, key `item`):\n{js}"
    );
    // NEGATIVE: the local is the ALIAS `value`, NOT the slot-prop key `item`.
    assert!(
        !js.contains("const item = $.derived(() => $$slotProps.item)"),
        "the aliased let: must bind the local `value`, not the key `item`:\n{js}"
    );
}

#[test]
fn component_destructuring_let_alias_fails_closed() {
    // A DESTRUCTURING `let:item={…}` alias is a broader decomposition this vertical does not
    // model — it fails CLOSED, never a silent drop. The refusal keys on the parsed pattern
    // NODE KIND (only a bare binding identifier is a one-name rename), NOT the collected-name
    // COUNT: a count gate wrongly accepts SINGLE-name destructures (`{ a }` / `[a]` each
    // collect exactly one name) and emits `const a = $.derived(() => $$slotProps.item)`,
    // silently swallowing the destructure. Every object/array pattern — single- OR multi-name
    // — must refuse.
    for (label, src) in [
        (
            "multi-name object",
            "<script>import Child from './Child.svelte'; let { p } = $props();</script>\n<Child let:item={{ a, b }}>x</Child>\n",
        ),
        (
            "single-name object",
            "<script>import Child from './Child.svelte'; let { p } = $props();</script>\n<Child let:item={{ a }}>x</Child>\n",
        ),
        (
            "single-name array",
            "<script>import Child from './Child.svelte'; let { p } = $props();</script>\n<Child let:item={[a]}>x</Child>\n",
        ),
    ] {
        assert_fail_closed_labeled(label, src, |s| {
            matches!(
                s,
                UnsupportedSvelteRuntimeSurface::ComponentOrSnippet {
                    construct: "let-directive",
                    ..
                }
            )
        });
    }
}

#[test]
fn component_class_directive_fails_closed() {
    // A `class:` directive on a COMPONENT is invalid Svelte (a component is not a DOM host) —
    // it fails CLOSED, NOT silently dropped (a silent no-op would emit `<Child class:foo={x}/>`
    // as `Child($$anchor, {})`, dropping the directive).
    assert_fail_closed(
        "<script>import Child from './Child.svelte'; let x = $state(0);</script>\n<Child class:foo={x} />\n",
        |s| {
            matches!(
                s,
                UnsupportedSvelteRuntimeSurface::ComponentOrSnippet {
                    construct: "directive",
                    ..
                }
            )
        },
    );
}

#[test]
fn component_style_directive_fails_closed() {
    // A `style:` directive on a COMPONENT is likewise invalid — fail CLOSED, never a silent
    // drop (sibling to the `class:` / `use:` / `transition:` component-directive refusal).
    assert_fail_closed(
        "<script>import Child from './Child.svelte'; let x = $state(0);</script>\n<Child style:color={x} />\n",
        |s| {
            matches!(
                s,
                UnsupportedSvelteRuntimeSurface::ComponentOrSnippet {
                    construct: "directive",
                    ..
                }
            )
        },
    );
}

#[test]
fn component_bind_prop_unwritable_root_fails_closed() {
    // A component `bind:value={p}` whose root resolves to a `$props()` PROP (a non-writable
    // root under the shared 5c writable-root policy) fails CLOSED — the component bind setter
    // is never synthesized from a non-writable root. The prop-bind refusal sweep scans only
    // `IrNode::Element`, so this gate is what catches a COMPONENT bind to a prop.
    assert_fail_closed(
        "<script>import Child from './Child.svelte'; let { p } = $props();</script>\n<Child bind:value={p} />\n",
        |s| matches!(s, UnsupportedSvelteRuntimeSurface::Binding { target, .. } if target == "value"),
    );
}

#[test]
fn svelte_window_size_bind_emits_bind_window_size() {
    // `<svelte:window bind:innerWidth={w}/>` → `$.bind_window_size('innerWidth', ($$value) =>
    // $.set(w, $$value, true))` — the dimension NAME first, NO host expr, setter-only, with
    // the window-host `should_proxy` flag.
    let js = emit(
        "<script>let w = $state(0);</script>\n<svelte:window bind:innerWidth={w} />\n",
        "App.svelte",
    );
    let n = normalize_js_cosmetics(&js);
    assert!(
        n.contains(&nc(
            "$.bind_window_size('innerWidth', ($$value) => $.set(w, $$value, true))"
        )),
        "bind:innerWidth must emit bind_window_size with the proxy flag:\n{js}"
    );
    // NEGATIVE: no host expr passed to bind_window_size, no DOM clone/append.
    assert!(
        !n.contains(&nc("$.bind_window_size($.window")),
        "no host expr for window_size:\n{js}"
    );
    assert!(
        !js.contains("$.from_html") && !js.contains("$.append"),
        "no DOM frame:\n{js}"
    );
    assert!(parses_as_js(&js), "module must be valid JS:\n{js}");
}

#[test]
fn svelte_window_scroll_bind_emits_bind_window_scroll() {
    // `<svelte:window bind:scrollX={sx}/>` → `$.bind_window_scroll('x', () => $.get(sx),
    // ($$value) => $.set(sx, $$value, true))` — the axis name REMAPPED to `'x'`, READ-WRITE
    // (get+set), with the proxy flag.
    let js = emit(
        "<script>let sx = $state(0);</script>\n<svelte:window bind:scrollX={sx} />\n",
        "App.svelte",
    );
    let n = normalize_js_cosmetics(&js);
    assert!(
        n.contains(&nc(
            "$.bind_window_scroll('x', () => $.get(sx), ($$value) => $.set(sx, $$value, true))"
        )),
        "bind:scrollX must emit bind_window_scroll('x', get, set):\n{js}"
    );
    // NEGATIVE: the runtime name is 'x', NEVER the literal 'scrollX'.
    assert!(
        !n.contains(&nc("'scrollX'")),
        "scrollX must remap to 'x', never 'scrollX':\n{js}"
    );
    assert!(parses_as_js(&js), "module must be valid JS:\n{js}");
}

#[test]
fn svelte_body_dimension_bind_emits_bind_element_size_against_body() {
    // `<svelte:body bind:clientWidth={w}/>` → `$.bind_element_size($.document.body,
    // 'clientWidth', ($$value) => $.set(w, $$value, true))` — the ELEMENT dimension helper
    // reused with the `$.document.body` host AND the `should_proxy` flag (the element form
    // has NO proxy flag).
    let js = emit(
        "<script>let w = $state(0);</script>\n<svelte:body bind:clientWidth={w} />\n",
        "App.svelte",
    );
    let n = normalize_js_cosmetics(&js);
    assert!(
        n.contains(&nc(
            "$.bind_element_size($.document.body, 'clientWidth', ($$value) => $.set(w, $$value, true))"
        )),
        "body bind:clientWidth must emit bind_element_size against $.document.body:\n{js}"
    );
    assert!(parses_as_js(&js), "module must be valid JS:\n{js}");
}

#[test]
fn svelte_body_scrollx_bind_is_invalid_and_fails_closed() {
    // `<svelte:body bind:scrollX={sx}/>` is an OFFICIAL COMPILE ERROR — `<svelte:body>` has
    // NO `scrollX`/`scrollY` (those are window-only). It must NEVER emit; Verter refuses it
    // at the HOST-SCOPED bind contract (`scrollX` is window-only, so the body host has no
    // routing) → the generic `Binding` refusal. The EXACT official `bind_invalid_target`
    // code/order is the D-29 deferral; the bind STILL fails closed (never emits).
    assert_fail_closed(
        "<script>let sx = $state(0);</script>\n<svelte:body bind:scrollX={sx} />\n",
        |s| matches!(s, UnsupportedSvelteRuntimeSurface::Binding { target, .. } if target == "scrollX"),
    );
}

#[test]
